query = input()
key = input()

if query.startswith("?"):
    query = query[1:]

found = False
value = ""

for pair in query.split("&"):
    # partition splits at the first "="; the value is "" if there is no "="
    name, separator, pair_value = pair.partition("=")
    if name == key:
        found = True
        value = pair_value
        break

if not found:
    print("NOT FOUND")
elif value == "":
    print("EMPTY")
else:
    print(value)

MINOR_WORDS = {"a", "an", "the", "and", "but", "or", "for", "nor",
               "on", "at", "to", "by", "of", "in"}

title = input()
result_words = []

for index, word in enumerate(title.split()):
    word = word.lower()

    if index > 0 and word in MINOR_WORDS:
        result_words.append(word)
    else:
        result_words.append(word[0].upper() + word[1:])

print(" ".join(result_words))

text = input()
kind = input()

if kind == "email":
    parts = text.split("@")
    if len(parts) != 2 or parts[0] == "" or parts[1] == "":
        print("INVALID")
    else:
        local = parts[0]
        domain = parts[1]
        if len(local) == 1:
            masked_local = "*"
        else:
            masked_local = local[0] + "*" * (len(local) - 1)
        print(masked_local + "@" + domain)

elif kind == "card":
    total_digits = 0
    for ch in text:
        if ch.isdigit():
            total_digits += 1

    if total_digits < 13 or total_digits > 19:
        print("INVALID")
    else:
        digits_seen = 0
        masked_chars = []
        for ch in text:
            if ch.isdigit():
                digits_seen += 1
                # hide every digit except the last 4
                if digits_seen <= total_digits - 4:
                    masked_chars.append("*")
                else:
                    masked_chars.append(ch)
            else:
                masked_chars.append(ch)    # keep spaces and hyphens
        print("".join(masked_chars))

else:
    print("INVALID")

roman = input()

values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
total = 0

for i, ch in enumerate(roman):
    has_next = i + 1 < len(roman)

    # A smaller symbol before a bigger one is subtracted (IV = 5 - 1)
    if has_next and values[ch] < values[roman[i + 1]]:
        total -= values[ch]
    else:
        total += values[ch]

print(total)
